using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    PropertyNamingPolicy = JsonNamingPolicy.CamelCase
};

// 1) Strongly-typed metadata retrieval — GetTypeInfo<T>()
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Type:       {personInfo.Type.Name}");
Console.WriteLine($"Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing — TryGetTypeInfo(Type, out ...)
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGet Person:  found={found}, type={info?.Type.Name}");

bool missing = options.TryGetTypeInfo(typeof(Uri), out JsonTypeInfo? info2);
Console.WriteLine($"TryGet Uri:     found={missing}, type={info2?.Type.Name ?? "(null)"}");

record Person(string Name, int Age);

